import{c as a,Q as e,j as s,m as d}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"非连续对齐搬出","description":"","frontmatter":{},"headers":[{"level":1,"title":"非连续对齐搬出","slug":"非连续对齐搬出"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Reg矢量计算/Reg数据搬运/非连续对齐搬出.md","filePath":"api/SIMD-API/基础API/Reg矢量计算/Reg数据搬运/非连续对齐搬出.md"}'),n={name:"api/SIMD-API/基础API/Reg矢量计算/Reg数据搬运/非连续对齐搬出.md"};function l(r,t,i,p,o,c){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="非连续对齐搬出" tabindex="-1">非连续对齐搬出 <a class="header-anchor" href="#非连续对齐搬出" aria-label="Permalink to &quot;非连续对齐搬出&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>Reg矢量计算数据搬运接口，适用于从RegTensor非连续对齐搬出到UB（以DataBlock为单位）。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 正常场景</span></span>
<span class="line"><span>template &lt;typename T = DefaultType, DataCopyMode dataMode, typename U&gt;</span></span>
<span class="line"><span>__simd_callee__ inline void StoreAlign(__ubuf__ T* dstAddr, U&amp; srcReg, uint32_t dataBlockStride, MaskReg&amp; mask);</span></span>
<span class="line"><span>// POST_MODE_UPDATE场景</span></span>
<span class="line"><span>template &lt;typename T = DefaultType, DataCopyMode dataMode, PostLiteral postMode, typename U&gt;</span></span>
<span class="line"><span>__simd_callee__ inline void StoreAlign(__ubuf__ T*&amp; dstAddr, U&amp; srcReg, uint32_t dataBlockStride, uint32_t repeatStride, MaskReg&amp; mask);</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> DataCopyMode模板参数说明</p><table tabindex="0"><thead><tr><th>DataCopyMode取值</th><th>含义</th></tr></thead><tbody><tr><td>DATA_BLOCK_COPY</td><td>用来在非连续对齐场景选择搬运模式。当前仅支持DataBlock搬运模式，即以DataBlock为粒度进行搬运。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>输入</td><td>模板参数，支持的数据类型为b8/b16/b32。</td></tr><tr><td>postMode</td><td>输入</td><td>用于控制是否使能post update，PostLiteral类型。</td></tr><tr><td>U</td><td>输入</td><td>RegTensor类型， 例如RegTensor&lt;half&gt;，由编译器自动推导，用户不需要填写。</td></tr><tr><td>srcReg</td><td>输入</td><td>源操作数，类型为RegTensor。</td></tr><tr><td>dstAddr</td><td>输入</td><td>目的操作数在UB上的起始地址。</td></tr><tr><td>dataBlockStride</td><td>输入</td><td>单次搬运相邻DataBlock间的间隔（前面一个DataBlock的头与后面DataBlock的头的间隔），单位为DataBlock。</td></tr><tr><td>repeatStride</td><td>输入</td><td>POST_MODE_NORMAL与POST_MODE_UPDATE场景下repeatStride含义不一致。 POST_MODE_NORMAL场景：实际搬运UB起始地址为dstAddr + repeatStride * 32。POST_MODE_UPDATE场景：实际搬运UB起始地址为dstAddr，搬运后执行地址更新dstAddr += repeatStride * 32。</td></tr><tr><td>mask</td><td>输入</td><td>MaskReg类型，指示在搬运过程中哪些元素有效。 某个DataBlock对应的32bit全为0时，即使该UB越界也不会报错。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__simd_vf__ inline void Compute(__ubuf__ T* dstAddr, __ubuf__ T* srcAddr, uint16_t repeatTimes)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; srcReg;</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg mask = AscendC::Reg::CreateMask&lt;T&gt;();</span></span>
<span class="line"><span>    for (uint16_t i = 0; i &lt; repeatTimes; ++i) {</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign&lt;T, AscendC::Reg::DataCopyMode::DATA_BLOCK_COPY, AscendC::Reg::PostLiteral::POST_MODE_UPDATE&gt;(srcReg, srcAddr, 1, i * 8, mask);</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign&lt;T, AscendC::Reg::DataCopyMode::DATA_BLOCK_COPY, AscendC::Reg::PostLiteral::POST_MODE_UPDATE&gt;(dstAddr, srcReg, 1, i * 8, mask);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,18)])])}const g=a(n,[["render",l]]);export{h as __pageData,g as default};
